class Minimum(BinaryOperator):
    """Returns the smaller of two objects."""

    def __init__(
        self,
        left: ChildSymbol,
        right: ChildSymbol,
    ):
        super().__init__("minimum", left, right)

    def __str__(self):
        """See :meth:`pybamm.Symbol.__str__()`."""
        return f"minimum({self.left!s}, {self.right!s})"

